t.script:
(function() {
    try {
        var links = document.querySelectorAll('link[rel="manifest"]');
        for (var i = 0; i < links.length; i++) {
            if (links[i].getAttribute('href') !== '/jandalah/sales/manifest.json') {
                links[i].parentNode.removeChild(links[i]);
            }
        }
        if ('serviceWorker' in navigator) {
            navigator.serviceWorker.register('/jandalah/sales/sw.js', { scope: '/my/sales' }).then(function() {
                console.log('Jandalah Sales SW registered');
            }).catch(function(e) {});
        }
    } catch(e) {}
})();

div.script:
let deferredSalesPrompt = null;

window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferredSalesPrompt = e;
});

function triggerDirectInstall() {
    if (deferredSalesPrompt) {
        deferredSalesPrompt.prompt();
        deferredSalesPrompt.userChoice.then((choiceResult) => {
            if (choiceResult.outcome === 'accepted') {
                const btn = document.getElementById('btn_direct_install_pwa');
                if (btn) {
                    btn.className = 'btn btn-success text-white fw-bold rounded-pill px-3 py-2 shadow-sm';
                    btn.innerHTML = ' تم تثبيت التطبيق بنجاح';
                }
            }
            deferredSalesPrompt = null;
        });
    } else {
        // If prompt is not ready or on iOS Safari, show modal
        const modalEl = document.getElementById('pwaSalesModal');
        if (modalEl && typeof bootstrap !== 'undefined') {
            const modal = bootstrap.Modal.getInstance(modalEl) || new bootstrap.Modal(modalEl);
            modal.show();
        }
    }
}

window.onProductSelect = function(selectEl) {
    const row = selectEl.closest('.product-row');
    const selectedOpt = selectEl.options[selectEl.selectedIndex];
    const price = selectedOpt.getAttribute('data-price') || 0.0;
    const priceInput = row.querySelector('.price-input');
    if (priceInput) {
        priceInput.value = parseFloat(price).toFixed(2);
    }
    window.calculateTotals();
};

window.calculateTotals = function() {
    let subtotal = 0;
    document.querySelectorAll('.product-row').forEach(row => {
        const qty = parseFloat(row.querySelector('.qty-input')?.value || 0);
        const price = parseFloat(row.querySelector('.price-input')?.value || 0);
        const disc = parseFloat(row.querySelector('.disc-input')?.value || 0);
        const lineTotal = (qty * price) * (1 - (disc / 100));
        if (lineTotal > 0) subtotal += lineTotal;
    });

    const tax = subtotal * 0.15;
    const grandTotal = subtotal + tax;

    const subEl = document.getElementById('subtotal_display');
    const taxEl = document.getElementById('tax_display');
    const totEl = document.getElementById('total_display');
    if (subEl) subEl.innerText = subtotal.toFixed(2) + ' ر.س';
    if (taxEl) taxEl.innerText = tax.toFixed(2) + ' ر.س';
    if (totEl) totEl.innerText = grandTotal.toFixed(2) + ' ر.س';
};

window.addProductRow = function() {
    const container = document.getElementById('products_container');
    const firstRow = container.querySelector('.product-row');
    const newRow = firstRow.cloneNode(true);
    newRow.querySelector('.qty-input').value = 1;
    newRow.querySelector('.price-input').value = 0.0;
    newRow.querySelector('.disc-input').value = 0;
    newRow.querySelector('.product-select').selectedIndex = 0;
    container.appendChild(newRow);
};

window.removeProductRow = function(btn) {
    const rows = document.querySelectorAll('.product-row');
    if (rows.length > 1) {
        btn.closest('.product-row').remove();
        window.calculateTotals();
    } else {
        alert('يجب أن تحتوي الفاتورة على صنف واحد على الأقل.');
    }
};

window.onCustomerChange = function(partnerId) {
    const box = document.getElementById('customer_credit_box');
    if (!partnerId) {
        if (box) box.classList.add('d-none');
        return;
    }
    fetch('/api/sales/customer/info', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ params: { partner_id: partnerId } })
    })
    .then(res => res.json())
    .then(data => {
        if (data && data.result && data.result.status === 'success') {
            const d = data.result.data;
            const balEl = document.getElementById('cust_balance');
            const limEl = document.getElementById('cust_limit');
            const avaEl = document.getElementById('cust_available');
            if (balEl) balEl.innerText = d.balance.toFixed(2) + ' ر.س';
            if (limEl) limEl.innerText = d.credit_limit.toFixed(2) + ' ر.س';
            if (avaEl) avaEl.innerText = d.available_credit.toFixed(2) + ' ر.س';
            if (box) box.classList.remove('d-none');
            const warn = document.getElementById('cust_warning');
            if (warn) {
                if (d.is_over_limit) {
                    warn.classList.remove('d-none');
                } else {
                    warn.classList.add('d-none');
                }
            }
        }
    })
    .catch(err => {
        console.warn('Customer info error:', err);
    });
};

// GPS Capture
if ("geolocation" in navigator) {
    navigator.geolocation.getCurrentPosition(function(pos) {
        const latEl = document.getElementById('order_latitude');
        const lngEl = document.getElementById('order_longitude');
        const stEl = document.getElementById('gps_status');
        if (latEl) latEl.value = pos.coords.latitude;
        if (lngEl) lngEl.value = pos.coords.longitude;
        if (stEl) stEl.innerHTML = ' تم تحديد موقع البيع (GPS) بنجاح';
    }, function() {
        const stEl = document.getElementById('gps_status');
        if (stEl) stEl.innerText = 'تعذر تحديد الـ GPS، سيتم الحفظ بدون إحداثيات.';
    });
}

if ("geolocation" in navigator) {
    navigator.geolocation.getCurrentPosition(function(pos) {
        const latEl = document.getElementById('cust_modal_lat');
        const lngEl = document.getElementById('cust_modal_lng');
        if (latEl) latEl.value = pos.coords.latitude;
        if (lngEl) lngEl.value = pos.coords.longitude;
    });
}
